import BreadcrumbFoundation, { BreadcrumbAdapter } from '@douyinfe/semi-foundation/breadcrumb/foundation';
import warning from '@douyinfe/semi-foundation/utils/warning';
import { isFunction } from 'lodash';
import '@douyinfe/semi-foundation/breadcrumb/breadcrumb.scss';
import { noop } from '@douyinfe/semi-foundation/utils/function';
import BaseComponent, { BaseProps } from '../_base/baseComponent';
import Popover from '../popover';
import BreadcrumbItem, { RouteProps, BreadcrumbItemInfo } from './item';
import BreadContext, { BreadContextType } from './bread-context';
import { TooltipProps } from '../tooltip';
import { IconMore } from '@douyinfe/semi-icons';

const clsPrefix = cssClasses.PREFIX;

export type { RouteProps, BreadcrumbItemProps, BreadcrumbItemInfo } from './item';
export interface showToolTipProps {
    width?: string | number;
    ellipsisPos?: 'end' | 'middle';
    opts?: TooltipProps
}

export type MoreType = 'default' | 'popover';

export interface BreadcrumbProps extends BaseProps {
    routes?: Array<RouteProps | string>;
    onClick?: (route: RouteProps, event: React.MouseEvent) => void;
    separator?: React.ReactNode;
    compact?: boolean;
    style?: React.CSSProperties;
    renderItem?: (route: RouteProps) => React.ReactNode;
    className?: string;
    showTooltip?: boolean | showToolTipProps;
    maxItemCount?: number;
    autoCollapse?: boolean;
    /* Customize the contents of the ellipsis area */
    renderMore?: (restItem: Array<React.ReactNode>) => React.ReactNode;
    /* Style type for ellipsis area */
    moreType?: MoreType;
    'aria-label'?: React.AriaAttributes['aria-label']
    activeIndex?: number
}

interface BreadcrumbState {
    isCollapsed: boolean
}

class Breadcrumb extends BaseComponent<BreadcrumbProps, BreadcrumbState> {
    static contextType: React.Context<BreadContextType> = BreadContext;

    static Item: typeof BreadcrumbItem = BreadcrumbItem;

    static propTypes = {
        activeIndex: propTypes.number,
        routes: propTypes.array,
        onClick: propTypes.func,
        separator: propTypes.node,
        compact: propTypes.bool,
        children: propTypes.node,
        style: propTypes.object,
        renderItem: propTypes.func,
        showTooltip: propTypes.oneOfType([
            propTypes.shape({
                width: propTypes.oneOfType([propTypes.string, propTypes.number]),
                ellipsisPos: propTypes.oneOf(['end', 'middle']),
                opts: propTypes.object,
            }),
            propTypes.bool,
        ]),
        className: propTypes.string,
        autoCollapse: propTypes.bool,
        maxItemCount: propTypes.number,

        /* Customize the contents of the ellipsis area */
        renderMore: propTypes.func,

        /* Type of ellipsis area */
        moreType: propTypes.oneOf(strings.MORE_TYPE),
        'aria-label': propTypes.string,
    };
    static defaultProps = {
        routes: [] as [],
        onClick: noop,
        renderItem: undefined as undefined,
        separator: '/',
        compact: true,
        showTooltip: {
            width: 150,
            ellipsisPos: 'end',
        },
        autoCollapse: true,
        moreType: 'default',
        maxItemCount: 4,
        'aria-label': 'Breadcrumb'
    };

    constructor(props: BreadcrumbProps) {
        super(props);
        this.foundation = new BreadcrumbFoundation(this.adapter);
        this.state = {
            isCollapsed: true,
        };
        this.onClick = this.onClick.bind(this);
    }

    get adapter(): BreadcrumbAdapter<BreadcrumbProps, BreadcrumbState> {
        return {
            ...super.adapter,
            notifyClick: (...args) => {
                this.props.onClick(...args);
            },
            expandCollapsed: () =>
                this.setState({
                    isCollapsed: false,
                }),
        };
    }

    componentDidMount() {
        this.foundation.init();
    }

    componentWillUnmount() {
        this.foundation.destroy();
    }

    renderPopoverMore(restItem: Array<React.ReactNode>) {
        const { separator } = this.props;
        const content = (
            <>
                {
                    restItem.map((item: React.ReactNode, idx: number) => (
                        <React.Fragment key={`restItem-${idx}`}>
                            {item}
                            {idx !== restItem.length - 1 &&
                                (
                                    <span className={`${clsPrefix}-restItem`}>
                                        {separator}
                                    </span>
                                )
                            }
                        </React.Fragment>
                    ))
                }
            </>
        );
        return (
            <Popover
                content={content}
                style={{
                    padding: 12,
                }}
                showArrow
            >
                <IconMore />
            </Popover>
        );
    }

    handleCollapse = (template: Array<React.ReactNode>, itemsLen: number) => {
        const { maxItemCount, renderMore, moreType } = this.props;
        const hasRenderMore = isFunction(renderMore);
        const restItem = template.slice(1, itemsLen - maxItemCount + 1);
        const spread = (
            <span className={`${clsPrefix}-collapse`} key={`more-${itemsLen}`}>
                <span className={`${clsPrefix}-item-wrap`}>
                    <span
                        role="button"
                        tabIndex={0}
                        aria-label="Expand breadcrumb items"
                        className={`${clsPrefix}-item ${clsPrefix}-item-more`}
                        onClick={item => this.foundation.handleExpand(item)}
                        onKeyPress={e => this.foundation.handleExpandEnterPress(e)}
                    >
                        {hasRenderMore && renderMore(restItem)}
                        {!hasRenderMore && moreType === 'default' && <IconMore />}
                        {!hasRenderMore && moreType === 'popover' && this.renderPopoverMore(restItem)}
                    </span>
                    <span className={`${clsPrefix}-separator`} x-semi-prop="separator">
                        {this.props.separator}
                    </span>
                </span>
            </span>
        );
        template.splice(1, itemsLen - maxItemCount, spread);
        return template;
    };

    renderRouteItems = (items: Array<RouteProps>, shouldCollapse: boolean, moreTypeIsPopover: boolean) => {
        const { renderItem, renderMore, maxItemCount } = this.props;
        const restItemLength = items.length - maxItemCount;
        const hasRenderMore = isFunction(renderMore);
        const template = (
            items.map((route, idx: number) => {
                const key = route._origin.key || `item-${route.name || route.path}-${idx}`;
                const inCollapseArea = idx > 0 && idx <= restItemLength;
                return (
                    <BreadcrumbItem
                        {...route}
                        key={key}
                        active={this.props.activeIndex !== undefined ? this.props.activeIndex===idx : idx === items.length - 1}
                        route={route._origin}
                        shouldRenderSeparator={ (idx !== items.length - 1) && !(shouldCollapse && (hasRenderMore || moreTypeIsPopover) && inCollapseArea)}
                    >
                        {renderItem ? renderItem(route._origin) : route.name}
                    </BreadcrumbItem>
                );
            })
        );
        return template;
    };

    renderList = (): Array<React.ReactNode> => {
        const {
            routes,
            children,
            autoCollapse,
            maxItemCount,
            renderMore,
            moreType
        } = this.props;
        const { isCollapsed } = this.state;
        const hasRoutes = routes && routes.length > 0;
        const items = hasRoutes ?
            this.foundation.genRoutes(routes) :
            React.Children.toArray(children);
        let template;
        const itemLength = items.length; // children length

        const restItemLength = itemLength - maxItemCount; // Omitted children items

        const shouldCollapse = items && autoCollapse && itemLength > maxItemCount && isCollapsed; // Whether the number of children exceeds, need to collapse

        const hasRenderMore = isFunction(renderMore); // Whether the user passes in the renderMore method
        const moreTypeIsPopover = moreType === 'popover';

        if (hasRoutes) {
            template = this.renderRouteItems(items, shouldCollapse, moreTypeIsPopover);
        } else {
            template = (
                items.map((item: any, idx: number) => {
                    const inCollapseArea = idx > 0 && idx <= restItemLength;
                    if (!item) {
                        return item;
                    }

                    warning(
                        item.type && !item.type.isBreadcrumbItem,
                        '[Semi Breadcrumb]: Only accepts Breadcrumb.Item as its children'
                    );

                    return React.cloneElement(item, {
                        key: `${idx}-item`,
                        active: this.props.activeIndex !== undefined ? this.props.activeIndex === idx : idx === items.length - 1,
                        shouldRenderSeparator: (idx !== items.length - 1) && (!(shouldCollapse && (hasRenderMore || moreTypeIsPopover) && inCollapseArea))
                    });
                })
            );
        }

        if (shouldCollapse) {
            return this.handleCollapse(template, items.length);
        }

        return template;
    };

    onClick = (info: BreadcrumbItemInfo, event: React.MouseEvent) => {
        this.foundation.handleClick(info, event);
    };

    render() {
        const breadcrumbs = this.renderList();
        const { compact, className, style, separator, showTooltip } = this.props;
        const sizeCls = cls(className,
            {
                [`${clsPrefix}-wrapper`]: true,
                [`${clsPrefix}-wrapper-compact`]: compact,
                [`${clsPrefix}-wrapper-loose`]: !compact
            }
        );
        return (
            <BreadContext.Provider
                value={{
                    onClick: this.onClick,
                    showTooltip,
                    compact,
                    separator,
                }}
            >
                <nav aria-label={this.props['aria-label']} className={sizeCls} style={style} {...this.getDataAttr(this.props)}>
                    {breadcrumbs}
                </nav>
            </BreadContext.Provider>
        );
    }
}

export default Breadcrumb;

import React, { Fragment } from 'react';
import cls from 'classnames';
import propTypes from 'prop-types';
import { cssClasses } from '@douyinfe/semi-foundation/breadcrumb/constants';
import BreadcrumbItemFoundation, { BreadcrumbItemAdapter, BreadcrumbItemInfo, Route } from '@douyinfe/semi-foundation/breadcrumb/itemFoundation';
import BaseComponent, { BaseProps } from '../_base/baseComponent';
import { noop } from '@douyinfe/semi-foundation/utils/function';
import BreadContext, { BreadContextType } from './bread-context';
import Typography, { EllipsisPos, ShowTooltip as ShowTooltipType } from '../typography';
import { merge, isUndefined, isNull } from 'lodash';

const clsPrefix = cssClasses.PREFIX;

export type { BreadcrumbItemInfo };

export interface RouteProps extends Route {
    icon?: React.ReactNode
}
export interface BreadcrumbItemProps extends BaseProps {
    onClick?: (item: RouteProps, e: React.MouseEvent) => void;
    icon?: React.ReactNode;
    href?: string;
    separator?: React.ReactNode;
    noLink?: boolean;
    active?: boolean;
    shouldRenderSeparator?: boolean;
    route?: RouteProps
}

type BreadcrumbItemState = Record<string, never>;

interface GetTooltipOptType {
    width: number;
    ellipsisPos: EllipsisPos;
    opts?: ShowTooltipType['opts']
}

export default class BreadcrumbItem extends BaseComponent<BreadcrumbItemProps, BreadcrumbItemState> {
    static isBreadcrumbItem = true;
    static contextType = BreadContext;

    static propTypes = {
        onClick: propTypes.func,
        route: propTypes.oneOfType([propTypes.object, propTypes.string]),
        name: propTypes.string,
        children: propTypes.node,
        active: propTypes.bool,
        shouldRenderSeparator: propTypes.bool,
        icon: propTypes.node,
        separator: propTypes.node,
        noLink: propTypes.bool,
    };

    static defaultProps = {
        onClick: noop,
        shouldRenderSeparator: true
    };

    context: BreadContextType;

    get adapter(): BreadcrumbItemAdapter<BreadcrumbItemProps, BreadcrumbItemState> {
        return {
            ...super.adapter,
            notifyClick: (...args) => {
                this.props.onClick(...args);
            },
            notifyParent: (...args) => {
                this.context.onClick(...args);
            },
        };
    }

    constructor(props: BreadcrumbItemProps) {
        super(props);
        this.foundation = new BreadcrumbItemFoundation(this.adapter);
    }

    componentDidMount() {
        this.foundation.init();
    }

    componentWillUnmount() {
        this.foundation.destroy();
    }

    renderIcon = () => {
        const iconType = this.props.icon;
        const { compact } = this.context;
        const iconSize = compact ? 'small' : 'default';
        const className = `${clsPrefix}-item-icon`;
        if (React.isValidElement(iconType)) {
            //@ts-ignore
            return React.cloneElement(iconType, { className, size: iconSize });
        }
        return iconType;
    };

    getTooltipOpt = () => {
        const { showTooltip } = this.context;
        if (!showTooltip) {
            return {
                width: 150,
                ellipsisPos: 'end',
            };
        }
        const defaultOpts = {
            width: 150,
            ellipsisPos: 'end',
            opts: {
                autoAdjustOverflow: true,
                position: 'top',
            },
        };
        if (typeof showTooltip === 'object') {
            return merge(defaultOpts, showTooltip);
        }
        return defaultOpts;
    };

    getItemInfo = (): BreadcrumbItemInfo => {
        let itemInfo: BreadcrumbItemInfo = {};
        const { route, children, href } = this.props;
        const hasHref = !isUndefined(href) && !isNull(href);
        if (route) {
            itemInfo = route;
        } else {
            itemInfo.name = children;
            if (hasHref) {
                itemInfo.href = href;
            }
        }
        return itemInfo;
    };

    renderBreadItem = () => {
        const { children } = this.props;
        const { compact } = this.context;
        const showTooltip = this.getTooltipOpt();
        const icon = this.renderIcon();
        if (Boolean(children) && typeof children === 'string') {
            const { opts, ellipsisPos, width } = showTooltip as GetTooltipOptType;
            return (
                <Fragment>
                    {icon}
                    <span className={`${clsPrefix}-item-title`}>
                        <Typography.Text
                            ellipsis={{
                                showTooltip: opts ? { opts } : false,
                                pos: ellipsisPos,
                            }}
                            // icon={this.renderIcon(icon)}
                            style={{ maxWidth: width }}
                            size={compact ? 'small' : 'normal'}
                        >
                            {children}
                        </Typography.Text>
                    </span>
                </Fragment>
            );
        }

        return (
            <Fragment>
                {icon}
                {children ? (
                    <span className={`${clsPrefix}-item-title ${clsPrefix}-item-title-inline`}>{children}</span>
                ) : null}
            </Fragment>
        );
    };

    renderItem = () => {
        const { href, active, noLink } = this.props;
        const hasHref = href !== null && typeof href !== 'undefined';
        const itemCls = cls({
            [`${clsPrefix}-item`]: true,
            [`${clsPrefix}-item-active`]: active,
            [`${clsPrefix}-item-link`]: !noLink,
        });
        const itemInner = this.renderBreadItem();
        const tag = active || !hasHref ? 'span' : 'a';
        const itemInfo = this.getItemInfo();
        return React.createElement(
            tag,
            {
                className: itemCls,
                onClick: e => this.foundation.handleClick(itemInfo, e),
                href,
            },
            itemInner
        );
    };

    render() {
        const {
            active,
            shouldRenderSeparator
            // children,
        } = this.props;
        const pageLabel = active ? { 'aria-current': 'page' as const } : {};
        const item = this.renderItem();
        const separator = this.props.separator || <span className={`${clsPrefix}-separator`}>{this.context.separator}</span>;
        const wrapperCLs = cls({
            [`${clsPrefix}-item-wrap`]: true,
            // [`${clsPrefix}-item-wrap-iconOnly`]: !!children && this.props.icon,
        });
        return (
            <span className={wrapperCLs} {...pageLabel} {...this.getDataAttr(this.props)}>
                {item}
                {shouldRenderSeparator && separator}
            </span>
        );
    }
}

