                    width: this.props.handleSize,
                    height: this.props.handleSize,
                    left: this.state.handlePosition,
                    top: `50%`,
                    transform: `translateY(-50%)`,
                    backgroundColor: ColorPickerFoundation.hsvaToHslString({ h: this.props.hue, s: 100, v: 100, a: 1 })
