    dashed?: boolean;
    /** The direction type of divider */
    layout?: 'horizontal' | 'vertical';
    /** Divider inline style */
    style?: CSSProperties
}

const Divider: React.FC<DividerProps> = props => {
    const {
        layout = 'horizontal',
        dashed,
        align = 'center',
        className,
        margin,
        style,
        children,
        ...rest
    } = props;

    const dividerClassNames = cls(`${prefixCls}-divider`, className, {
